# Summarize each experiment
for eid in [1,2,3,5,9,10,11]:
    try:
        df = pd.read_csv(eval(f"experiment_{eid}_csv"))
        cols = [c for c in df.columns]
        print(f"--- exp {eid} n={len(df)} cols={cols}")
        if 'CapacityRetention' in df:
            print("  CapRet mean", round(df['CapacityRetention'].mean(),3))
        num = df.select_dtypes('number')
        print("  corr w CapRet:")
        if 'CapacityRetention' in num:
            print(num.corr()['CapacityRetention'].round(3).to_dict())
    except Exception as e:
        print(eid, "err", e)
